using System.Data;using JamunaBank.Procurement.API.Data;using JamunaBank.Procurement.API.DTOs;using JamunaBank.Procurement.API.Repositories.Base;using JamunaBank.Procurement.API.Repositories.Interfaces;
namespace JamunaBank.Procurement.API.Repositories.Implementations;
public sealed class RequisitionFormRepository(IStoredProcedureExecutor procedures):BaseRepository(procedures),IRequisitionFormRepository
{
 public async Task<ReadyRequisitionPageDto>GetReadyAsync(string?search,string?type,long?divisionId,DateOnly?from,DateOnly?to,int page,int size,CancellationToken ct){var ds=await StoredProcedures.QueryDataSetAsync("dbo.usp_Procurement_ReadyForProcurement_Get",[SqlParameterFactory.Input("@Search",SqlDbType.NVarChar,search,200),SqlParameterFactory.Input("@RequisitionType",SqlDbType.VarChar,type,20),SqlParameterFactory.Input("@ConcernDivisionId",SqlDbType.BigInt,divisionId),SqlParameterFactory.Input("@FromDate",SqlDbType.Date,from?.ToDateTime(TimeOnly.MinValue)),SqlParameterFactory.Input("@ToDate",SqlDbType.Date,to?.ToDateTime(TimeOnly.MinValue)),SqlParameterFactory.Input("@PageNumber",SqlDbType.Int,page),SqlParameterFactory.Input("@PageSize",SqlDbType.Int,size)],ct);var items=ds.Tables[0].Rows.Cast<DataRow>().Select(x=>new ReadyRequisitionDto((long)x["REQUISITION_ID"],(string)x["REQUISITION_NO"],(DateTime)x["REQUESTED_DATE"],(string)x["ORG_UNIT_NAME"],(string)x["ASSET_NAMES"],(string)x["REQUISITION_TYPES"],x["CONCERN_DIVISION_ID"]==DBNull.Value?null:(long)x["CONCERN_DIVISION_ID"],x["CONCERN_DIVISION_NAME"]as string,(DateTime)x["READY_DATE"])).ToArray();var total=ds.Tables.Count>1&&ds.Tables[1].Rows.Count>0?Convert.ToInt32(ds.Tables[1].Rows[0]["TOTAL_COUNT"]):0;var divisions=ds.Tables.Count>2?ds.Tables[2].Rows.Cast<DataRow>().Select(x=>new ConcernDivisionOptionDto((long)x["CONCERN_DIVISION_ID"],(string)x["ORG_UNIT_NAME"])).ToArray():[];return new(items,page,size,total,(int)Math.Ceiling(total/(double)size),divisions);}
 public async Task<RequisitionFormDto?>GetFormAsync(long id,string actor,CancellationToken ct){var ds=await StoredProcedures.QueryDataSetAsync("dbo.usp_Procurement_RequisitionForm_Get",[SqlParameterFactory.Input("@RequisitionId",SqlDbType.BigInt,id),SqlParameterFactory.Input("@ActorEmployeeId",SqlDbType.VarChar,actor,30)],ct);if(ds.Tables.Count<4||ds.Tables[0].Rows.Count==0)return null;var h=ds.Tables[0].Rows[0];var header=new RequisitionFormHeaderDto((long)h["REQUISITION_ID"],(string)h["REQUISITION_NO"],(DateTime)h["REQUESTED_DATE"],(string)h["REQUESTING_UNIT"],(string)h["REQUESTED_BY"],h["DESIGNATION"]as string,h["CONCERN_DIVISION_NAME"]as string,(string)h["JUSTIFICATION"],(string)h["CURRENT_STATUS"],(DateTime)h["GENERATED_ON"],(string)h["GENERATED_BY"],h["GENERATED_BY_UNIT"]as string);var items=ds.Tables[1].Rows.Cast<DataRow>().Select(x=>new RequisitionFormItemDto((long)x["REQ_ITEM_ID"],(string)x["ASSET_NAME"],(string)x["REQ_TYPE"],(decimal)x["QUANTITY"],(string)x["PURPOSE_JUSTIFICATION"],x["ADDITIONAL_SPEC_REQUIREMENT"]as string,x["SPECIFICATIONS"]as string,x["ASSET_TAG_NO"]as string,x["SERIAL_NO"]as string,x["CURRENT_CONDITION"]as string,x["ADDITIONAL_INFO"]as string)).ToArray();var history=ds.Tables[2].Rows.Cast<DataRow>().Select(x=>new RequisitionFormHistoryDto(Convert.ToInt32(x["SEQUENCE"]),(string)x["STAGE_NAME"],(string)x["OFFICIAL_NAME"],x["DESIGNATION"]as string,x["UNIT_NAME"]as string,(string)x["DECISION"],x["REMARKS"]as string,(DateTime)x["ACTION_DATETIME"])).ToArray();var s=ds.Tables[3].Rows[0];return new(header,items,history,new((string)s["CURRENT_STATUS"],(DateTime)s["READY_DATE"]));}
}
